#!/bin/bash
# Uninstall script for Sempliva Tiles
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Sempliva Tiles..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Sempliva Tiles if running..."
pkill -f "Sempliva Tiles" 2>/dev/null || true

# Unload service com.sempliva.TilesHelper
echo "Unloading service com.sempliva.TilesHelper..."
launchctl unload -w /Library/LaunchAgents/com.sempliva.TilesHelper.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.sempliva.TilesHelper.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.sempliva.TilesHelper.plist 2>/dev/null || true

# Kill application with bundle ID com.sempliva.Tiles if running
echo "Stopping application with bundle ID com.sempliva.Tiles if running..."
killall -9 "com.sempliva.Tiles" 2>/dev/null || true

# Remove /Applications/Tiles.app
echo "Removing /Applications/Tiles.app..."
if [ -d "/Applications/Tiles.app" ]; then
    rm -rf "/Applications/Tiles.app" 2>/dev/null || true
elif [ -f "/Applications/Tiles.app" ]; then
    rm -f "/Applications/Tiles.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.sempliva.Tiles
echo "Removing $HOME/Library/Application Support/com.sempliva.Tiles..."
if [ -d "$HOME/Library/Application Support/com.sempliva.Tiles" ]; then
    rm -rf "$HOME/Library/Application Support/com.sempliva.Tiles" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.sempliva.Tiles" ]; then
    rm -f "$HOME/Library/Application Support/com.sempliva.Tiles" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/com.sempliva.Tiles
echo "Removing $HOME/Library/Caches/com.sempliva.Tiles..."
if [ -d "$HOME/Library/Caches/com.sempliva.Tiles" ]; then
    rm -rf "$HOME/Library/Caches/com.sempliva.Tiles" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.sempliva.Tiles" ]; then
    rm -f "$HOME/Library/Caches/com.sempliva.Tiles" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.semplive.Tiles.plist
echo "Removing $HOME/Library/Preferences/com.semplive.Tiles.plist..."
if [ -d "$HOME/Library/Preferences/com.semplive.Tiles.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.semplive.Tiles.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.semplive.Tiles.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.semplive.Tiles.plist" 2>/dev/null || true
fi

